class QuizPack {
  const QuizPack({
    required this.id,
    required this.title,
    required this.subtitle,
    required this.icon,
    required this.accent,
    required this.questions,
    this.difficulty = 'Intermédiaire',
    this.minutes = 8,
    this.xp = 120,
    this.featured = false,
  });

  final String id;
  final String title;
  final String subtitle;
  final IconData icon;
  final int accent;
  final List<QuizQuestion> questions;
  final String difficulty;
  final int minutes;
  final int xp;
  final bool featured;

  Color get accentColor => Color(accent);
}

